function defaultStudy12(f){const x=String(f||'').toLowerCase();if(x.includes('stricture'))return'rgu';if(x.includes('prostate'))return'mpmri';if(x.includes('stone'))return'ctstone';if(x.includes('bph'))return'uroflow';if(x.includes('urodynamic'))return'pfs';if(x.includes('kidney'))return'renalmass';if(x.includes('adrenal'))return'adrenal';if(x.includes('testis'))return'scrotal';if(x.includes('bladder')||x.includes('utuc'))return'cystoscopy';return'uroflow';}
